//! Ledger: for each UI action UAD Console was traced performing, drive the same action through
//! our `ViewState` + `EngineMixer` and compare the engine traffic.
//!
//! Sources (`fixtures/console-trace/`, regenerated by `tools/ledger/extract_*.py`):
//! - `v131-ui-writes.txt`: Console **1.3.1** on macOS against UA Mixer Engine 12, from a
//!   loopback capture. This is the source of truth where the two differ.
//! - `ui-writes.txt`: Console 1.2.x under Wine against the open-apollo daemon.
//!
//! Commands are compared as [`Wire`] shapes: verb, property path, query parameters (minus
//! `func_id`), value kind, and the `/UndoRecording` bracket. The **core** match (verb, path,
//! bracket, value kind) is asserted per scenario, except scenarios listed in
//! [`KNOWN_DIVERGENT`] (a ratchet: remove an entry when our side is fixed). The **strict** 1.3.1
//! match also requires the same query parameters (`context_type=main`); its failures are counted
//! against [`MAX_QUERY_MISMATCH`]. Everything goes to `$LEDGER_OUT/trace-equivalence.json`.

use std::collections::BTreeSet;
use std::sync::Arc;

use engine_model::{EngineMixer, UNISON_SLOT};
use rack::{Action, Control, ControlId, MixerModel, ViewState};

fn fixture() -> String {
    format!("{}/../ua-engine/tests/fixtures/apollo-x4-12.0.0.snapshot.json", env!("CARGO_MANIFEST_DIR"))
}

fn out_dir() -> std::path::PathBuf {
    let d = std::env::var_os("LEDGER_OUT").map(Into::into).unwrap_or_else(|| std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/ledger"));
    std::fs::create_dir_all(&d).unwrap();
    d
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum Kind {
    Bool,
    Num,
    /// The literal `"default"` (Console 1.3.1's double-click reset).
    Default,
    Str(String),
    Json,
    None,
}

/// One command reduced to what must match.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Wire {
    verb: String,
    prop: String,
    query: BTreeSet<String>,
    kind: Kind,
}

impl Wire {
    fn parse(text: &str) -> Wire {
        let (verb, rest) = text.split_once(' ').unwrap_or((text, ""));
        let (path, value) = rest.split_once(' ').unwrap_or((rest, ""));
        let (path, q) = path.split_once('?').unwrap_or((path, ""));
        let prop = path.strip_suffix("/value").unwrap_or(path).to_owned();
        let query = q.split('&').filter(|kv| !kv.is_empty() && !kv.starts_with("func_id=")).map(str::to_owned).collect();
        let v = value.trim();
        let kind = match v {
            "" => Kind::None,
            "true" | "false" => Kind::Bool,
            "\"default\"" => Kind::Default,
            _ if v.starts_with('"') => Kind::Str(v.trim_matches('"').to_owned()),
            _ if v.starts_with('{') || v.starts_with('[') => Kind::Json,
            _ if v.parse::<f64>().is_ok() => Kind::Num,
            _ => Kind::Str(v.to_owned()),
        };
        Wire { verb: verb.to_owned(), prop, query, kind }
    }

    fn is_undo(&self) -> bool {
        self.prop == "/UndoRecording"
    }

    fn core(&self) -> (String, String, Kind) {
        (self.verb.clone(), self.prop.clone(), self.kind.clone())
    }
}

/// Collapses repeated sets of one property (a drag streams many) to one entry, so a 61-set drag
/// and our 3-set drag compare equal.
fn collapse(cmds: &[Wire]) -> Vec<Wire> {
    let mut out: Vec<Wire> = Vec::new();
    for c in cmds {
        if let Some(last) = out.last() {
            if !c.is_undo() && last.core() == c.core() {
                continue;
            }
        }
        out.push(c.clone());
    }
    out
}

/// The traced UI actions, as blocks of commands.
fn traced(text: &str) -> Vec<Vec<Wire>> {
    text.split("\n\n").map(|b| b.lines().filter(|l| !l.starts_with('#') && !l.is_empty()).map(Wire::parse).collect::<Vec<_>>()).filter(|b| !b.is_empty()).collect()
}

/// The first traced action whose non-bracket commands touch `prop_suffix` (and, if given, have
/// value kind `kind`).
fn find_traced(blocks: &[Vec<Wire>], prop_suffix: &str, kind: Option<&Kind>) -> Option<Vec<Wire>> {
    blocks.iter().find(|b| b.iter().any(|w| !w.is_undo() && w.prop.ends_with(prop_suffix) && kind.is_none_or(|k| &w.kind == k))).map(|b| collapse(b))
}

/// Re-targets a traced action at another strip (`/inputs/3/` → `/inputs/1/`) when the fixture's
/// layout differs (the x4 12.0.0 fixture links inputs 2/3 as a stereo pair).
fn retarget(block: Option<Vec<Wire>>, from: &str, to: &str) -> Option<Vec<Wire>> {
    block.map(|b| b.into_iter().map(|mut w| {
        w.prop = w.prop.replace(from, to);
        w
    }).collect())
}

struct Driver {
    model: EngineMixer,
    view: ViewState,
    seen: u64,
}

impl Driver {
    fn new() -> Driver {
        let model = EngineMixer::from_snapshot(fixture()).expect("fixture");
        let seen = model.store().writer().suppressed_count();
        Driver { model, view: ViewState::default(), seen }
    }

    fn act(&mut self, a: Action) {
        self.view.dispatch(a, &mut self.model);
    }

    fn id(strip: &str, control: Control) -> ControlId {
        ControlId { strip: Arc::from(strip), control }
    }

    /// A press on a toggle (mouse down + up).
    fn toggle(&mut self, strip: &str, control: Control) {
        self.act(Action::Toggle(Self::id(strip, control)));
    }

    fn tap(&mut self, strip: &str, control: Control) {
        self.act(Action::Tap(Self::id(strip, control)));
    }

    /// A drag: gesture with a few values (Interaction's shape).
    fn drag(&mut self, strip: &str, control: Control, values: &[f64]) {
        let id = Self::id(strip, control);
        self.act(Action::GestureBegin(id.clone()));
        for v in values {
            self.act(Action::Set(id.clone(), *v));
        }
        self.act(Action::GestureEnd(id));
    }

    /// The commands written since the last call (writes stay suppressed offline; the writer
    /// keeps their text).
    fn take(&mut self) -> Vec<Wire> {
        self.model.store_mut().flush();
        let w = self.model.store().writer();
        let n = (w.suppressed_count() - self.seen) as usize;
        self.seen = w.suppressed_count();
        let recent: Vec<&str> = w.recent_suppressed().collect();
        recent[recent.len().saturating_sub(n)..].iter().map(|t| Wire::parse(t)).collect()
    }
}

struct Outcome {
    scenario: &'static str,
    source: &'static str,
    ui_action: &'static str,
    console: Vec<String>,
    ours: Vec<String>,
    core_match: bool,
    strict_match: bool,
    known_divergent: bool,
    note: String,
}

fn show(w: &[Wire]) -> Vec<String> {
    w.iter()
        .map(|w| {
            let q = if w.query.is_empty() { String::new() } else { format!("?{}", w.query.iter().cloned().collect::<Vec<_>>().join("&")) };
            format!("{} {}{} {:?}", w.verb, w.prop, q, w.kind)
        })
        .collect()
}

/// Scenario name → why it diverges today. Remove an entry when our side is fixed.
const KNOWN_DIVERGENT: &[(&str, &str)] = &[
    ("insert-assign", "Console sends the assign unbracketed (no /UndoRecording); we commit it inside a bracket"),
    ("unison-assign", "Console sends the assign unbracketed (no /UndoRecording); we commit it inside a bracket"),
];

/// Offline audit writes omit request queries (assigned by the live connection).
/// The separate live wire-profile test checks those queries.
const MAX_QUERY_MISMATCH: usize = 4;

#[test]
fn console_ui_actions_produce_the_same_engine_traffic() {
    let v131 = traced(include_str!("fixtures/console-trace/v131-ui-writes.txt"));
    let v12 = traced(include_str!("fixtures/console-trace/ui-writes.txt"));
    let in0 = "/devices/0/inputs/0";
    let in1 = "/devices/0/inputs/1";
    let in2 = "/devices/0/inputs/2";
    let aux0 = "/devices/0/auxs/0";
    let mut outcomes = Vec::new();
    let mut check = |scenario: &'static str, source: &'static str, ui_action: &'static str, console: Option<Vec<Wire>>, ours: Vec<Wire>, note: String| {
        // 1.3.1 is the source of truth where it was captured (Mute, Pan); elsewhere the 1.2.x
        // shape stands. protocol/v131/map.json: 1.3.1 tags mixer-control sets (Mute, Pan,
        // FaderLevelTapered, CRMonitorLevelTapered) `context_type=main`; 1.2.x sent Phase and
        // RecordPreEffects with a plain func_id, and no 1.3.1 sample of those exists yet.
        let console = console.unwrap_or_else(|| panic!("{scenario}: no traced action in {source}"));
        let ours = collapse(&ours);
        let core = |v: &[Wire]| v.iter().map(Wire::core).collect::<Vec<_>>();
        let core_match = core(&console) == core(&ours);
        let strict_match = core_match && console.iter().zip(&ours).all(|(a, b)| a.query == b.query);
        let known = KNOWN_DIVERGENT.iter().any(|(s, _)| *s == scenario);
        outcomes.push(Outcome { scenario, source, ui_action, console: show(&console), ours: show(&ours), core_match, strict_match, known_divergent: known, note });
    };

    // ---- Console 1.3.1 (loopback capture) ----
    let mut d = Driver::new();
    d.toggle(in1, Control::Mute);
    check("input-mute", "v131", "click an input's M", find_traced(&v131, "/inputs/1/Mute", None), d.take(), String::new());

    let mut d = Driver::new();
    d.drag(in0, Control::PanL, &[0.45, 0.40, 0.30]);
    check("pan-drag", "v131", "drag a mono input's pan knob", find_traced(&v131, "/inputs/0/Pan", Some(&Kind::Num)), d.take(), String::new());

    let mut d = Driver::new();
    let pan = Driver::id(in0, Control::PanL);
    for a in [Action::GestureBegin(pan.clone()), Action::Reset(pan.clone(), 0.5), Action::GestureEnd(pan)] { d.act(a); }
    check("pan-reset", "v131", "double-click a pan knob (reset)", find_traced(&v131, "/inputs/0/Pan", Some(&Kind::Default)), d.take(), String::new());

    // ---- Console 1.2.x (Wine + open-apollo daemon traces) ----
    let mut d = Driver::new();
    d.drag("monitor", Control::MonitorLevel, &[0.2, 0.25, 0.15]);
    check("monitor-drag", "v12", "drag the monitor knob", find_traced(&v12, "/outputs/18/CRMonitorLevelTapered", None), d.take(), String::new());

    let mut d = Driver::new();
    d.drag(aux0, Control::Fader, &[0.7, 0.78]);
    check("aux-fader-drag", "v12", "drag an aux return's fader", find_traced(&v12, "/auxs/0/FaderLevelTapered", None), d.take(), String::new());

    let mut d = Driver::new();
    d.toggle(in2, Control::Preamp(Arc::from("phase")));
    let note = if d.model.store().value(&format!("{in2}/preamps/0/Phase")).is_none() { "fixture has no Phase on input 2".into() } else { String::new() };
    check("preamp-phase", "v12", "click Ø on a preamp", find_traced(&v12, "/preamps/0/Phase", None), d.take(), note);

    let mut d = Driver::new();
    d.toggle(in1, Control::RecMon);
    let traced = retarget(find_traced(&v12, "/inputs/3/RecordPreEffects", None), "/inputs/3/", "/inputs/1/");
    check("rec-mon", "v12", "click a strip's UAD REC/MON (traced on input 3; the fixture pairs 2/3)", traced, d.take(), String::new());

    let mut d = Driver::new();
    let name = "UAD 4K Buss Compressor";
    let insert = Driver::id(aux0, Control::Insert(0));
    match d.model.plugin_catalog().iter().position(|p| p.name == name) {
        Some(i) => {
            d.view.browser.selected = Some(i as u16);
            d.act(Action::Tap(insert.clone()));
        }
        None => d.model.set_text(&insert, name), // the route's own effect (catalog trimmed in the fixture)
    }
    let assign = d.take();
    check("insert-assign", "v12", "assign a plug-in to an empty aux insert", find_traced(&v12, "/auxs/0/effects/0/EffectName", Some(&Kind::Str(name.into()))), assign, String::new());
    d.tap(aux0, Control::InsertRemove(0));
    check("insert-remove", "v12", "remove an insert (REMOVE modifier / menu)", find_traced(&v12, "/auxs/0/effects/0/EffectName", Some(&Kind::Str(String::new()))), d.take(), String::new());

    let mut d = Driver::new();
    d.model.set_text(&Driver::id(in0, Control::Insert(UNISON_SLOT)), "UAD ADA Flanger");
    check("unison-assign", "v12", "assign a Unison preamp", find_traced(&v12, "/preamps/0/effects/0/EffectName", None), d.take(), String::new());

    // ---- report and assertions ----
    let strict_fail = outcomes.iter().filter(|o| o.core_match && !o.strict_match).count();
    let json: Vec<serde_json::Value> = outcomes
        .iter()
        .map(|o| {
            serde_json::json!({
                "scenario": o.scenario, "source": o.source, "ui_action": o.ui_action,
                "console": o.console, "ours": o.ours, "core_match": o.core_match,
                "strict_match": o.strict_match, "known_divergent": o.known_divergent,
                "divergence": KNOWN_DIVERGENT.iter().find(|(s, _)| *s == o.scenario).map(|(_, why)| *why),
                "note": o.note,
            })
        })
        .collect();
    std::fs::write(out_dir().join("trace-equivalence.json"), serde_json::to_string_pretty(&json).unwrap()).unwrap();
    for o in &outcomes {
        eprintln!(
            "{:<15} {:<5} core {} strict {}{}",
            o.scenario,
            o.source,
            if o.core_match { "ok  " } else { "DIFF" },
            if o.strict_match { "ok" } else { "DIFF" },
            if o.known_divergent { "  (known)" } else { "" }
        );
        if !o.core_match {
            eprintln!("    console: {:?}\n    ours:    {:?}", o.console, o.ours);
        }
    }
    for o in &outcomes {
        if o.known_divergent {
            assert!(!o.core_match, "{}: now matches Console; remove it from KNOWN_DIVERGENT", o.scenario);
        } else {
            assert!(o.core_match, "{}: engine traffic differs from Console:\n  console {:?}\n  ours    {:?}", o.scenario, o.console, o.ours);
        }
    }
    assert!(strict_fail <= MAX_QUERY_MISMATCH, "{strict_fail} scenarios miss Console 1.3.1's query parameters (max {MAX_QUERY_MISMATCH})");
}

/// Console 1.3.1 wire-profile rules (protocol/v131/MAP.md "Console 1.3.1 client profile") that
/// fail today, with the work that fixes them. A ratchet: the test prints rules that now pass.
const KNOWN_WIRE_GAPS: &[(&str, &str)] = &[
    ("undo-refresh", "rapid consecutive gestures coalesce the delayed undo-list refresh; the final list is refreshed"),
];

/// Live against a `MockEngine` (writes on): the exact frames we send for a mute click, a pan
/// drag and a pan double-click, checked against Console 1.3.1's wire profile. Report:
/// `$LEDGER_OUT/wire-profile.json`.
#[test]
fn wire_profile_matches_console_131() {
    use std::time::{Duration, Instant};
    use ua_engine::{MockEngine, MockOptions, Snapshot, Status};

    let tree = Snapshot::load(fixture()).unwrap().tree;
    let server = MockEngine::start(tree, MockOptions::default()).unwrap();
    let mut m = EngineMixer::connect(server.endpoint(), true);
    let deadline = Instant::now() + Duration::from_secs(10);
    while *m.store().status() != Status::Live {
        m.pump();
        assert!(Instant::now() < deadline, "not live");
        std::thread::sleep(Duration::from_millis(5));
    }
    let mark = server.received_commands().len();
    let mut view = ViewState::default();
    let id = |c: Control| ControlId { strip: Arc::from("/devices/0/inputs/1"), control: c };
    // Mute click; pan drag (3 mouse events); pan double-click (Interaction: begin, reset, end).
    view.dispatch(Action::Toggle(id(Control::Mute)), &mut m);
    let pan = id(Control::PanL);
    view.dispatch(Action::GestureBegin(pan.clone()), &mut m);
    for v in [0.45, 0.40, 0.35] {
        view.dispatch(Action::Set(pan.clone(), v), &mut m);
        m.pump();
        std::thread::sleep(Duration::from_millis(20));
    }
    view.dispatch(Action::GestureEnd(pan.clone()), &mut m);
    for a in [Action::GestureBegin(pan.clone()), Action::Reset(pan.clone(), 0.5), Action::GestureEnd(pan.clone())] {
        view.dispatch(a, &mut m);
    }
    let settle = Instant::now() + Duration::from_millis(400);
    while Instant::now() < settle {
        m.pump();
        std::thread::sleep(Duration::from_millis(10));
    }
    let sent: Vec<String> = server.received_commands()[mark..].to_vec();
    let sets: Vec<&String> = sent.iter().filter(|c| c.starts_with("set ")).collect();
    let undo: Vec<&&String> = sets.iter().filter(|c| c.starts_with("set /UndoRecording/")).collect();
    let controls: Vec<&&String> = sets.iter().filter(|c| !c.starts_with("set /UndoRecording/")).collect();
    let has = |c: &str, q: &str| c.split(' ').nth(1).is_some_and(|p| p.split_once('?').is_some_and(|(_, qs)| qs.split('&').any(|kv| kv.starts_with(q))));
    // After each closing bracket, a `get /UndoRedo/values?cmdID=15` before the next bracket opens.
    let closes: Vec<usize> = sent.iter().enumerate().filter(|(_, c)| c.starts_with("set /UndoRecording/") && c.ends_with(" false")).map(|(i, _)| i).collect();
    let refreshed = !closes.is_empty()
        && closes.iter().all(|&i| sent[i + 1..].iter().take_while(|c| !(c.starts_with("set /UndoRecording/") && c.ends_with(" true"))).any(|c| c.starts_with("get /UndoRedo/values") && c.contains("cmdID=15")));
    let pan_sets = controls.iter().filter(|c| c.contains("/inputs/1/Pan/")).count();
    let rules: Vec<(&str, bool, String)> = vec![
        ("set-func-id", !controls.is_empty() && controls.iter().filter(|c| !c.ends_with("\"default\"")).all(|c| has(c, "func_id=")), "every control set carries ?func_id=<n>".into()),
        ("set-context-type", !controls.is_empty() && controls.iter().filter(|c| !c.ends_with("\"default\"")).all(|c| has(c, "context_type=main")), "mixer-control sets carry context_type=main".into()),
        ("undo-func-id", !undo.is_empty() && undo.iter().all(|c| has(c, "func_id=")), "/UndoRecording sets carry ?func_id=<n>".into()),
        ("undo-refresh", refreshed, "get /UndoRedo/values?cmdID=15 after every gesture".into()),
        ("reset-default", controls.iter().any(|c| c.contains("/inputs/1/Pan/value") && c.ends_with(" \"default\"")), "double-click reset sends \"default\"".into()),
        ("brackets", undo.len() >= 6 && undo.len() % 2 == 0, format!("{} /UndoRecording sets for 3 gestures", undo.len())),
        // P2 (informational): Console sends one set per mouse event (3 here); we coalesce.
        ("drag-uncoalesced (P2, info)", pan_sets >= 4, format!("{pan_sets} Pan sets for 3 drag events + reset")),
    ];
    let report: Vec<serde_json::Value> = rules
        .iter()
        .map(|(r, ok, what)| serde_json::json!({ "rule": r, "pass": ok, "what": what, "known_gap": KNOWN_WIRE_GAPS.iter().find(|(k, _)| k == r).map(|(_, w)| *w) }))
        .collect();
    std::fs::write(out_dir().join("wire-profile.json"), serde_json::to_string_pretty(&serde_json::json!({ "sent": sent, "rules": report })).unwrap()).unwrap();
    for (r, ok, what) in &rules {
        eprintln!("{:<28} {}  {what}", r, if *ok { "pass" } else { "FAIL" });
    }
    for (r, ok, _) in &rules {
        let known = KNOWN_WIRE_GAPS.iter().any(|(k, _)| k == r);
        if r.contains("(P2, info)") {
            continue;
        }
        if known && *ok {
            eprintln!("{r}: now passes; remove it from KNOWN_WIRE_GAPS");
        }
        assert!(*ok || known, "wire rule {r} fails and is not a known gap");
    }
}
